// Writes the F&O Studio agents from scripts/agent-definitions.js: agents/<id>.agent.md, the routing instructions
// agents/fno-agents.instructions.md, and the chatAgents / chatInstructions contributions in package.json.
// Usage: node scripts/build-agents.js [--check]   (--check fails when a generated file is missing or out of date)
const fs = require('fs');
const path = require('path');
const { agents, Rules } = require('./agent-definitions');

const root = path.resolve(__dirname, '..');
const dir = path.join(root, 'agents');
const check = process.argv.includes('--check');
const q = s => JSON.stringify(s);

const problems = [];
const byId = new Map(agents.map(a => [a.id, a]));
for (const a of agents) {
    if (agents.filter(b => b.id === a.id || b.name === a.name).length > 1) problems.push(`duplicate agent ${a.id} / ${a.name}`);
    for (const r of a.rules) if (!Rules[r]) problems.push(`${a.id}: unknown rule ${r}`);
    if (!!a.readOnly !== a.rules.includes('readOnly')) problems.push(`${a.id}: readOnly flag and rules disagree`);
    if (a.readOnly && a.rules.includes('changes')) problems.push(`${a.id}: a read-only agent can't have the changes rule`);
    for (const h of a.handoffs ?? []) if (!byId.has(h.agent)) problems.push(`${a.id}: handoff to unknown agent ${h.agent}`);
}
if (problems.length) {
    console.error(problems.join('\n'));
    process.exit(1);
}

function agentFile(a) {
    const handoffs = a.handoffs ?? [];
    const head = ['---', `name: ${q(a.name)}`, `description: ${q(a.description)}`, `argument-hint: ${q(a.hint)}`];
    if (handoffs.length) {
        head.push('handoffs:');
        for (const h of handoffs)
            head.push(`  - label: ${q(h.label)}`, `    agent: ${q(byId.get(h.agent).name)}`, `    prompt: ${q(h.prompt)}`, '    send: false');
    }
    head.push('---');
    const next = handoffs.length
        ? handoffs.map(h => `- ${h.label}: offer **${byId.get(h.agent).name}** when this step is done.`).join('\n')
        : '- When the task is done, say which F&O agent fits the next step, if any.';
    return `${head.join('\n')}
<!-- Generated by scripts/build-agents.js from scripts/agent-definitions.js; edit there. -->

${a.body}

## Rules
${a.rules.map(r => '- ' + Rules[r]).join('\n')}

## Next steps
${next}
`;
}

function routingFile() {
    const rows = agents.map(a => `| ${a.name} | ${a.audience} | ${a.description} |`).join('\n');
    return `---
name: "F&O Studio agents"
description: "Dynamics 365 Finance & Operations (D365FO, F&O, X++) requests: which F&O Studio agent fits the task, and the rules for changes."
---
<!-- Generated by scripts/build-agents.js from scripts/agent-definitions.js; edit there. -->

# F&O Studio agents

F&O Studio adds agents for Dynamics 365 Finance & Operations work. When the user hasn't selected one of them and the request
is about D365FO:

- If one agent clearly fits, say which one in one line and offer to switch to it.
- If a self-contained part of the task clearly fits an agent (for example a review after a change, or triage of a pasted
  error), you may run that agent as a subagent and use its result. Don't do this for small questions you can answer directly.
- Agents started this way follow the same rules: ${Rules.changes}

| Agent | For | Use it to |
|---|---|---|
${rows}
`;
}

const outputs = new Map(agents.map(a => [path.join(dir, a.id + '.agent.md'), agentFile(a)]));
outputs.set(path.join(dir, 'fno-agents.instructions.md'), routingFile());

const pkgPath = path.join(root, 'package.json');
const pkgText = fs.readFileSync(pkgPath, 'utf8');
const pkg = JSON.parse(pkgText);
const contributes = {};
for (const [key, value] of Object.entries(pkg.contributes)) {
    if (key === 'chatAgents' || key === 'chatInstructions') continue;
    contributes[key] = value;
    if (key === 'chatParticipants') {
        contributes.chatAgents = agents.map(a => ({ path: `./agents/${a.id}.agent.md` }));
        contributes.chatInstructions = [{ path: './agents/fno-agents.instructions.md' }];
    }
}
if (!contributes.chatAgents) {
    contributes.chatAgents = agents.map(a => ({ path: `./agents/${a.id}.agent.md` }));
    contributes.chatInstructions = [{ path: './agents/fno-agents.instructions.md' }];
}
pkg.contributes = contributes;
outputs.set(pkgPath, JSON.stringify(pkg, null, 2) + '\n');

const stale = [];
for (const [file, text] of outputs) {
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : null;
    if (current === text) continue;
    stale.push(path.relative(root, file));
    if (!check) {
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, text);
    }
}
const known = new Set([...outputs.keys()].map(f => path.basename(f)));
const extra = fs.existsSync(dir) ? fs.readdirSync(dir).filter(f => !known.has(f)) : [];
for (const f of extra) {
    stale.push('agents/' + f + ' (not defined)');
    if (!check) fs.unlinkSync(path.join(dir, f));
}

if (check) {
    if (stale.length) {
        console.error('Out of date (run node scripts/build-agents.js):\n  ' + stale.join('\n  '));
        process.exit(1);
    }
    console.log(`${agents.length} agents up to date.`);
} else {
    console.log(stale.length ? 'Wrote:\n  ' + stale.join('\n  ') : `${agents.length} agents already up to date.`);
}
